// Some portions generated by Claude
import type { EdgeCurve, Graph, GraphTransform } from "./graph-types.ts";
import { GRAPH_HEIGHT, GRAPH_WIDTH } from "./graph-config.ts";

/** World-space vertices survive pan/zoom; the GPU applies the viewport matrix. */
export function createGraphVertexCache() {
  let previousNodes: Graph["nodes"] | undefined;
  let previousEdges: Graph["edges"] | undefined;
  let previousCurves: ReadonlyMap<string, EdgeCurve> | undefined;
  let vertices = { lines: new Float32Array(0), points: new Float32Array(0) };
  return (graph: Graph, curves?: ReadonlyMap<string, EdgeCurve>) => {
    if (graph.nodes === previousNodes && graph.edges === previousEdges && curves === previousCurves) return vertices;
    const nodes = new Map(graph.nodes.map(node => [node.id, node]));
    const segments = curves ? 12 : 1;
    let lines = new Float32Array(graph.edges.length * 4 * segments);
    const points = new Float32Array(graph.nodes.length * 2);
    let lineOffset = 0, pointOffset = 0;
    for (const edge of graph.edges) {
      const source = nodes.get(edge.source), target = nodes.get(edge.target);
      if (source?.x === undefined || source.y === undefined || target?.x === undefined || target.y === undefined) continue;
      const curve = curves?.get(edge.id);
      if (curve?.points) {
        // A stepped route has few segments; draw them exactly instead of sampling a quadratic.
        if (lineOffset + (curve.points.length - 1) * 4 > lines.length) {
          const grown = new Float32Array(lines.length + curve.points.length * 4 + 1024);
          grown.set(lines);
          lines = grown;
        }
        for (let step = 1; step < curve.points.length; step++) {
          lines[lineOffset++] = curve.points[step - 1].x; lines[lineOffset++] = curve.points[step - 1].y;
          lines[lineOffset++] = curve.points[step].x; lines[lineOffset++] = curve.points[step].y;
        }
        continue;
      }
      if (curve) {
        let x = curve.start.x, y = curve.start.y;
        for (let step = 1; step <= segments; step++) {
          const t = step / segments, u = 1 - t;
          const nextX = u * u * curve.start.x + 2 * u * t * curve.control.x + t * t * curve.end.x;
          const nextY = u * u * curve.start.y + 2 * u * t * curve.control.y + t * t * curve.end.y;
          lines[lineOffset++] = x; lines[lineOffset++] = y;
          lines[lineOffset++] = nextX; lines[lineOffset++] = nextY;
          x = nextX; y = nextY;
        }
        continue;
      }
      lines[lineOffset++] = source.x; lines[lineOffset++] = source.y;
      lines[lineOffset++] = target.x; lines[lineOffset++] = target.y;
    }
    for (const node of graph.nodes) {
      if (node.x === undefined || node.y === undefined) continue;
      points[pointOffset++] = node.x; points[pointOffset++] = node.y;
    }
    previousNodes = graph.nodes; previousEdges = graph.edges; previousCurves = curves;
    vertices = { lines: lines.subarray(0, lineOffset), points: points.subarray(0, pointOffset) };
    return vertices;
  };
}

export function graphClipTransform(transform: GraphTransform, width: number, height: number) {
  const renderWidth = width > 0 ? width : GRAPH_WIDTH;
  const renderHeight = height > 0 ? height : GRAPH_HEIGHT;
  const viewBoxScale = Math.min(renderWidth / GRAPH_WIDTH, renderHeight / GRAPH_HEIGHT);
  return {
    scaleX: 2 * transform.k * viewBoxScale / renderWidth,
    scaleY: -2 * transform.k * viewBoxScale / renderHeight,
    offsetX: (2 * transform.x - GRAPH_WIDTH) * viewBoxScale / renderWidth,
    offsetY: (GRAPH_HEIGHT - 2 * transform.y) * viewBoxScale / renderHeight,
  };
}
